<?php declare(strict_types=1); use Core\Http\Router; use Modules\Permissions\Controllers\RoleController; return function (Router $router): void { $router->group([ 'prefix' => 'admin/roles', 'middleware' => ['web', 'auth'], 'name' => 'admin.roles.', ], function (Router $router): void { $router->get('/', [RoleController::class, 'index']) ->middleware('permission:permissions.manage') ->name('index'); $router->post('/{id}/permissions', [RoleController::class, 'updatePermissions']) ->middleware('permission:permissions.manage') ->where('id', '\d+') ->name('updatePermissions'); }); }; 